def is_safe_state(available, allocation, need):
    work = available[:]
    finish = [False] * len(allocation)
    while True:
        progressed = False
        for p in range(len(allocation)):
            if not finish[p] and all(need[p][r] <= work[r] for r in range(len(work))):
                work = [work[r] + allocation[p][r] for r in range(len(work))]
                finish[p] = True
                progressed = True
        if not progressed:
            break
    return all(finish)  # safe iff every process could finish

def request(pid, req, available, allocation, need):
    if any(req[r] > need[pid][r] for r in range(len(req))):
        raise ValueError("request exceeds declared max")
    if any(req[r] > available[r] for r in range(len(req))):
        return False  # not enough available right now — must wait
    # tentatively grant, then check safety
    tmp_avail = [available[r] - req[r] for r in range(len(req))]
    tmp_alloc = [row[:] for row in allocation]
    tmp_alloc[pid] = [tmp_alloc[pid][r] + req[r] for r in range(len(req))]
    tmp_need = [row[:] for row in need]
    tmp_need[pid] = [tmp_need[pid][r] - req[r] for r in range(len(req))]
    if is_safe_state(tmp_avail, tmp_alloc, tmp_need):
        return True  # commit the tentative state
    return False  # would be unsafe — deny and roll back, even though resources exist
```

The key line is the last one: even if `available` has enough resources to satisfy the request right now, the request is still **denied** if granting it would leave the system in an unsafe state — that's the entire difference between avoidance and simply checking availability.
